insert into stories (text, name, age, city, story_year, status) values
  ('גדלתי על הכרמל ואני עדיין עוצרת כל בוקר לראות את המפרץ. כשהייתה לי הצעה לעבור לברלין, הבנתי שאין שם אף אחד שיביא לי מרק כשאני חולה. פה השכנה שלי עושה את זה בלי לשאול. זה למה אני פה.', 'נועה', 29, 'חיפה', 2026, 'approved'),
  ('הגעתי לפה בגיל שש עם מזוודה אחת. אבא שלי נישק את האדמה בנמל. היום יש לי שבעה נכדים שמדברים עברית עם מבטא של המדבר. אני לא הולך לשום מקום.', 'אבי', 67, 'באר שבע', 2026, 'approved'),
  ('כי ביום שישי בשוק הכרמל כולם צועקים ואף אחד לא כועס. כי אפשר לדבר עם זר בתור ולצאת עם חבר. כי פה אני מרגישה שמה שאני עושה משנה.', 'מאיה', 22, 'תל אביב', 2026, 'approved'),
  ('אני מורה להיסטוריה. כל שנה אני לוקח כיתה לעיר העתיקה ורואה את העיניים שלהם נפתחות. ההיסטוריה הזאת היא לא בספר, היא מתחת לרגליים. אני רוצה שגם הילדים שלי ירגישו את זה.', 'יוסף', 41, 'ירושלים', 2026, 'approved'),
  ('פונינו מהבית לחודשים ארוכים. חזרנו לגינה מלאה עשבים ולתריס שבור. שתלנו הכל מחדש. הבית הזה שלנו ואנחנו נשארים לשמור עליו.', 'דנה', 34, 'קריית שמונה', 2026, 'approved'),
  ('במילואים הבנתי מי האנשים שלידי. מתכנת, חקלאי, סטודנט ואבא לשלושה, כולם באותו בוץ. אף פעם לא הרגשתי חלק ממשהו גדול כל כך.', 'עומר', 26, 'רמת גן', 2026, 'approved'),
  ('כל ערב אני הולכת על הטיילת עם חברה מגיל עשר. ראינו את העיר הזאת גדלה מכפר קטן. הים פה הוא הים שלי.', 'רחל', 78, 'נהריה', 2026, 'approved'),
  ('כי סבא שלי נלחם בשביל זה וגם אבא שלי. עכשיו התור שלי לבנות פה משהו טוב יותר. אני רוצה להיות מהנדס ולהישאר.', 'איתי', 17, 'מודיעין', 2026, 'approved'),
  ('אני צוללת. מתחת למים של מפרץ אילת יש עולם שלם שרוב העולם לא מכיר. וכשאני עולה למעלה אני רואה ארבע מדינות ובית אחד.', 'סיוון', 38, 'אילת', 2026, 'approved'),
  ('אני רופא במחלקה לטיפול נמרץ. ראיתי יהודים וערבים מחזיקים ידיים מחוץ לחדר ניתוח. זה הבית של כולנו, ואני פה כדי לשמור עליו בריא.', 'מוחמד', 45, 'שפרעם', 2026, 'approved'),
  ('עוד סיבה: הפלאפל ברחוב החלוץ. ברצינות.', 'נועה', 29, 'חיפה', 2026, 'approved'),
  ('אנחנו נחזור לבנות. כל בית, כל עץ, כל שביל. כי הקהילה הזאת היא המשפחה שלי ואנחנו עוד נצחק פה שוב.', 'שירה', 31, 'קיבוץ בארי', 2026, 'approved');
